 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    src=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==4]
    mark=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]
    out=[row[:] for row in grid]
    for r,c in mark: out[r][c]=0
    rlo,rhi=min(r for r,c in src),max(r for r,c in src)
    clo,chi=min(c for r,c in src),max(c for r,c in src)
    mrlo,mrhi=min(r for r,c in mark),max(r for r,c in mark)
    mclo,mchi=min(c for r,c in mark),max(c for r,c in mark)
    # Marker orientation picks reflection axis. A vertical stem T marker means
    # reflect source vertically across the gap to its nearest side.
    rows={r for r,c in mark}; cols={c for r,c in mark}
    vertical = len(rows) > len(cols)
    if vertical:
        # copy on opposite side of marker, with reflection axis between objects
        if mrlo > rhi:
            axis2=rhi+mrlo-1
        else:
            axis2=rlo+mrhi+1
        for r,c in src:
            rr=axis2-r
            if 0<=rr<h: out[rr][c]=4
    else:
        if mclo > chi:
            axis2=chi+mclo-1
        else:
            axis2=clo+mchi+1
        for r,c in src:
            cc=axis2-c
            if 0<=cc<w: out[r][cc]=4
    return out
